# RW2DM_GROUP: Group, AddToGroup, RemoveFromGroup, Ungroup, UngroupAll: group membership. The script rw2dm_group_script.txt is generated by rw2dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW2_GROUP_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW2_GROUP_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw2dm_group_script.txt" 2>&1)" || { echo "$RW2_GROUP_OUT" | tail -40; echo "FAIL RW2DM_GROUP_run: script exited non-zero"; fail=1; RW2_GROUP_OUT=""; }
else
  RW2_GROUP_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw2dm_group_script.txt" 2>&1)" || { echo "$RW2_GROUP_OUT" | tail -40; echo "FAIL RW2DM_GROUP_run: script exited non-zero"; fail=1; RW2_GROUP_OUT=""; }
fi
rw2_group_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_GROUP_OUT"; }
# rw2_group_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw2_group_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw2_group_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW2DM_GROUP_$name: $desc (objects: $got)"
  else echo "FAIL RW2DM_GROUP_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw2_group_state group "1:point:Default 2:curve:Default" "Group of 1 and 2 reports its size and SelGroup then selects exactly 1 and 2" "Group [0-9]+ created with 2 object\(s\)" "2 object\(s\) selected"
rw2_group_state two_groups "1:point:Default 2:curve:Default 3:surface:Default 4:polysurface:Default" "a second Group of 3 and 4 makes SelGroup reach all four" "4 object\(s\) selected"
rw2_group_state add "1:point:Default 2:curve:Default 3:surface:Default" "AddToGroup of 2 (grouped) and a new object: after a fresh Group of 1 and 2 only, adding 2 and 3 puts 3 into the group of 2 (SelGroup: 1, 2, 3)" "3 object\(s\) selected"
rw2_group_state add_same "1:point:Default 3:surface:Default" "after AddToGroup 1 and 3 are in the SAME group: SetGroupName on the selection {1, 3} names exactly 1 group" "SetGroupName: 1 group\(s\) named 'Frame'"
rw2_group_state add_none "1:point:Default 2:curve:Default 3:surface:Default" "AddToGroup with no grouped object in the selection warns and changes nothing: SelGroup still reaches 1, 2, 3 only" "! Selection contains no group"
rw2_group_state remove "1:point:Default 3:surface:Default" "RemoveFromGroup of 2 detaches only 2: SelGroup reaches 1 and 3" 
rw2_group_state remove_rest "-" "the remaining members 1 and 3 are still one group (SetGroupName on {1, 3} names 1 group), and removing both leaves no group" "SetGroupName: 1 group\(s\) named 'Rest'" "0 object\(s\) selected"
rw2_group_state ungroup "3:surface:Default 4:polysurface:Default" "Ungroup of 1 and 2 (grouped together) leaves the group {3, 4}: SelGroup reaches 3 and 4" "2 object\(s\) selected"
rw2_group_state ungroup_one "4:polysurface:Default" "Ungroup of 3 alone takes just 3 out of its group: SelGroup reaches only 4" "1 object\(s\) selected"
rw2_group_state ungroup_none "4:polysurface:Default" "Ungroup of an ungrouped object warns and changes nothing: 4 is still the only grouped object" "! Ungroup: none of the selected objects is in a group"
rw2_group_state ungroupall "-" "UngroupAll removes every group at once: after two groups, SelGroup reaches nothing" "UngroupAll: 4 object\(s\) ungrouped" "0 object\(s\) selected"
